export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortFailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type InvalidOrMissingBody = Readonly<{
  code: "invalid_command" | "not_found";
}>;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: AbortFailedAt;
  classification: AbortClassification;
  rejections: readonly Rejection[];
}>;

export interface ServiceResponse {
  status: number;
  body: PublicShipment | InvalidOrMissingBody | AbortBody;
}

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type ProviderAttempt =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      failedAt: Provider;
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

type DispatchPlan = Readonly<{
  nextProvider: Provider;
  rejections: readonly Rejection[];
}>;

const allowedReasons = ["unsupported_route", "unsupported_parcel"] as const;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isSafeNonnegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return allowedReasons.some((reason) => reason === value);
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rejections = value.map((entry) => {
    if (
      !isObject(entry) ||
      !isProvider(entry.provider) ||
      !isRefusalReason(entry.reason)
    ) {
      return undefined;
    }
    return {
      provider: entry.provider,
      reason: entry.reason,
    } satisfies Rejection;
  });

  if (rejections.some((entry) => entry === undefined)) {
    return undefined;
  }

  return rejections.filter((entry) => entry !== undefined);
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeNonnegativeInteger(value.nowMs) ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const base = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } satisfies ShipmentFields;

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }

  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeNonnegativeInteger(value.dispatchedAtMs)
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }

  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeNonnegativeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...base,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }

  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...base,
        state: "unavailable",
        rejections,
      };
    }
  }

  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections,
      };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: AbortFailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections,
  };
}

function logAbort(
  logger: ShippingDependencies["logger"],
  body: AbortBody,
): void {
  logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: body.rejections,
  });
}

function requestFor(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyKnownRejection(
  provider: Provider,
  error: unknown,
  nowMs: number,
): ProviderAttempt {
  if (!isObject(error)) {
    return {
      kind: "aborted",
      failedAt: provider,
      classification: "unknown_failure",
    };
  }

  if (provider === "atlas") {
    if (error.code === "cannot_ship") {
      if (isRefusalReason(error.reason)) {
        return {
          kind: "refused",
          rejection: { provider, reason: error.reason },
        };
      }
      return {
        kind: "aborted",
        failedAt: provider,
        classification: "invalid_provider_response",
      };
    }
    if (error.code === "rate_limited") {
      if (
        typeof error.retryAtMs === "number" &&
        Number.isSafeInteger(error.retryAtMs) &&
        error.retryAtMs > nowMs
      ) {
        return { kind: "throttled", provider, retryAtMs: error.retryAtMs };
      }
      return {
        kind: "aborted",
        failedAt: provider,
        classification: "invalid_provider_response",
      };
    }
    return {
      kind: "aborted",
      failedAt: provider,
      classification: "unknown_failure",
    };
  }

  if (error.type === "rejected") {
    if (isObject(error.details) && isRefusalReason(error.details.reason)) {
      return {
        kind: "refused",
        rejection: { provider, reason: error.details.reason },
      };
    }
    return {
      kind: "aborted",
      failedAt: provider,
      classification: "invalid_provider_response",
    };
  }

  if (error.type === "throttled") {
    if (
      isObject(error.details) &&
      typeof error.details.retryAtMs === "number" &&
      Number.isSafeInteger(error.details.retryAtMs) &&
      error.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", provider, retryAtMs: error.details.retryAtMs };
    }
    return {
      kind: "aborted",
      failedAt: provider,
      classification: "invalid_provider_response",
    };
  }

  return {
    kind: "aborted",
    failedAt: provider,
    classification: "unknown_failure",
  };
}

function classifyConfirmation(
  provider: Provider,
  confirmation: unknown,
): ProviderAttempt {
  if (!isObject(confirmation)) {
    return {
      kind: "aborted",
      failedAt: provider,
      classification: "invalid_provider_response",
    };
  }

  if (provider === "atlas" && isNonemptyString(confirmation.bookingId)) {
    return { kind: "confirmed", provider, bookingId: confirmation.bookingId };
  }

  if (provider === "beacon" && isNonemptyString(confirmation.reference)) {
    return { kind: "confirmed", provider, bookingId: confirmation.reference };
  }

  return {
    kind: "aborted",
    failedAt: provider,
    classification: "invalid_provider_response",
  };
}

async function attemptProvider(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<ProviderAttempt> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, confirmation);
  } catch (error) {
    return classifyKnownRejection(provider, error, nowMs);
  }
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

function nextPlanAfterRefusal(
  rejections: readonly Rejection[],
): DispatchPlan | undefined {
  if (!hasRefusal(rejections, "beacon")) {
    return { nextProvider: "beacon", rejections };
  }
  return undefined;
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  decision: StoredShipment,
  event: Record<string, unknown>,
  failureRejections: readonly Rejection[],
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipment.id, decision);
  } catch {
    const body = abortBody(
      shipment.id,
      "repository",
      "repository_failure",
      failureRejections,
    );
    logAbort(dependencies.logger, body);
    return { status: 500, body };
  }

  dependencies.logger.info(event);
  if (decision.state === "deferred") {
    return { status: 202, body: publicShipment(decision) };
  }
  if (decision.state === "unavailable") {
    return { status: 422, body: publicShipment(decision) };
  }
  return { status: 200, body: publicShipment(decision) };
}

async function runDispatchPlan(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  plan: DispatchPlan,
): Promise<ServiceResponse> {
  const request = requestFor(shipment, command.recipient);
  const attempt = await attemptProvider(
    dependencies,
    plan.nextProvider,
    request,
    command.nowMs,
  );

  switch (attempt.kind) {
    case "confirmed": {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider: attempt.provider,
        bookingId: attempt.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      return saveDecision(
        dependencies,
        shipment,
        dispatched,
        {
          shipmentId: shipment.id,
          action: "dispatched",
          provider: attempt.provider,
        },
        plan.rejections,
      );
    }
    case "throttled": {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "deferred",
        nextProvider: attempt.provider,
        retryAtMs: attempt.retryAtMs,
        rejections: plan.rejections,
      };
      return saveDecision(
        dependencies,
        shipment,
        deferred,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider: attempt.provider,
          retryAtMs: attempt.retryAtMs,
          rejections: plan.rejections,
        },
        plan.rejections,
      );
    }
    case "refused": {
      const rejections = [...plan.rejections, attempt.rejection];
      const nextPlan = nextPlanAfterRefusal(rejections);
      if (nextPlan !== undefined) {
        return runDispatchPlan(dependencies, shipment, command, nextPlan);
      }

      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "unavailable",
        rejections,
      };
      return saveDecision(
        dependencies,
        shipment,
        unavailable,
        {
          shipmentId: shipment.id,
          action: "unavailable",
          rejections,
        },
        rejections,
      );
    }
    case "aborted": {
      const body = abortBody(
        shipment.id,
        attempt.failedAt,
        attempt.classification,
        plan.rejections,
      );
      logAbort(dependencies.logger, body);
      return { status: 500, body };
    }
  }
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      const body = abortBody(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      logAbort(dependencies.logger, body);
      return { status: 500, body };
    }

    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseShipment(value);
    if (shipment === undefined) {
      const body = abortBody(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      logAbort(dependencies.logger, body);
      return { status: 500, body };
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }

    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }

    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return runDispatchPlan(dependencies, shipment, command, {
        nextProvider: shipment.nextProvider,
        rejections: shipment.rejections,
      });
    }

    return runDispatchPlan(dependencies, shipment, command, {
      nextProvider: "atlas",
      rejections: [],
    });
  }

  return { handle };
}
